package gui;
import data.DataStore;import model.User;import service.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;
public class ProfilePanel extends Theme.BackgroundPanel{private final MainApp app;private final JTextField name=new JTextField(),age=new JTextField(),height=new JTextField(),weight=new JTextField(),steps=new JTextField(),sleep=new JTextField(),allergy=new JTextField();private final JComboBox<String> activity=box("Sedentary","Lightly Active","Moderately Active","Very Active"),diet=box("Vegetarian","Non-Vegetarian","Vegan","Eggetarian"),workout=box("Full Body","Home Training","Cardio","Yoga & Mobility"),goal=box("Weight Loss","Weight Gain","Maintain Weight","Muscle Building","General Fitness");private final JLabel bmi=Theme.header("BMI —");
 public ProfilePanel(MainApp a){app=a;setOpaque(false);setLayout(new BorderLayout(15,15));setBorder(new EmptyBorder(22,28,18,28));add(Theme.title("PROFILE & PERSONALIZATION"),BorderLayout.NORTH);JPanel g=new JPanel(new GridLayout(0,2,12,12));g.setOpaque(false);add(g,"Name",name);add(g,"Age",age);add(g,"Height (cm)",height);add(g,"Current Weight (kg)",weight);add(g,"Activity Level",activity);add(g,"Fitness Goal",goal);add(g,"Food Preference",diet);add(g,"Workout Style",workout);add(g,"Daily Step Goal",steps);add(g,"Sleep Goal",sleep);JPanel allergyBox=new JPanel(new BorderLayout(6,0)); allergyBox.setOpaque(false);
        allergyBox.add(allergy,BorderLayout.CENTER);
        JButton chooseAllergy=Theme.secondaryButton("CHOOSE");
        chooseAllergy.addActionListener(e->{String selected=AllergySelector.choose(this,allergy.getText());if(selected!=null)allergy.setText(selected);});
        allergyBox.add(chooseAllergy,BorderLayout.EAST);
        add(g,"Allergies / Avoid",allergyBox);JScrollPane sc=new JScrollPane(g);sc.setBorder(null);sc.getViewport().setOpaque(false);add(sc,BorderLayout.CENTER);JPanel bot=Theme.darkPanel(new FlowLayout(FlowLayout.RIGHT));bot.add(bmi);JButton save=Theme.primaryButton("SAVE & RE-CALIBRATE ✦"),back=Theme.secondaryButton("Dashboard");bot.add(save);bot.add(back);add(bot,BorderLayout.SOUTH);save.addActionListener(e->save());back.addActionListener(e->app.showPanel(MainApp.DASHBOARD));}
 private JComboBox<String> box(String...x){JComboBox<String>b=new JComboBox<>(x);Theme.styleComboBox(b);return b;}private void add(JPanel p,String l,JComponent c){JPanel q=Theme.darkPanel(new BorderLayout(4,4));q.add(Theme.mutedLabel(l.toUpperCase()),BorderLayout.NORTH);if(c instanceof JTextField)Theme.styleTextField((JTextField)c);q.add(c,BorderLayout.CENTER);p.add(q);}public void refresh(){User u=app.getCurrentUser();if(u==null)return;name.setText(u.getName());age.setText(""+u.getAge());height.setText(""+u.getHeight());weight.setText(""+u.getWeight());activity.setSelectedItem(u.getActivityLevel());diet.setSelectedItem(u.getFoodPreference());workout.setSelectedItem(u.getWorkoutPreference());steps.setText(""+u.getDailyStepGoal());sleep.setText(""+u.getSleepGoalHours());allergy.setText(u.getAllergies());goal.setSelectedItem(u.getFitnessGoal());bmi.setText(String.format("BMI %.1f • %s",BMICalculator.calculateBMI(u.getWeight(),u.getHeight()),BMICalculator.getCategory(BMICalculator.calculateBMI(u.getWeight(),u.getHeight()))));}
 private void save(){try{User u=app.getCurrentUser();u.setName(name.getText().trim());u.setAge(Integer.parseInt(age.getText()));u.setHeight(Double.parseDouble(height.getText()));u.setWeight(Double.parseDouble(weight.getText()));u.setActivityLevel((String)activity.getSelectedItem());u.setFitnessGoal((String)goal.getSelectedItem());u.setFoodPreference((String)diet.getSelectedItem());u.setWorkoutPreference((String)workout.getSelectedItem());u.setDailyStepGoal(Integer.parseInt(steps.getText()));u.setSleepGoalHours(Double.parseDouble(sleep.getText()));u.setAllergies(allergy.getText());
 java.util.Map<String,String> update=new java.util.LinkedHashMap<>();update.put("name",u.getName());update.put("age",String.valueOf(u.getAge()));update.put("height",String.valueOf(u.getHeight()));update.put("weight",String.valueOf(u.getWeight()));update.put("activity",u.getActivityLevel());update.put("goal",u.getFitnessGoal());update.put("diet",u.getFoodPreference());update.put("workout",u.getWorkoutPreference());update.put("stepsGoal",String.valueOf(u.getDailyStepGoal()));update.put("sleepGoal",String.valueOf(u.getSleepGoalHours()));update.put("allergies",u.getAllergies());
 data.BackendClient.updateProfile(update);DataStore.saveUserChanges();refresh();JOptionPane.showMessageDialog(this,"Profile updated. Diet, workout and coach recommendations have been recalibrated.");app.showPanel(MainApp.DASHBOARD);}catch(Exception e){JOptionPane.showMessageDialog(this,"Please enter valid values.");}}
}
